/* Host-side boundary model of the guard added by the candidate patch.
 * Not a kernel test: it verifies the predicate semantics only. */
#define NR_syscalls 312
#define GUARD(nr) ((nr) < 0 || (nr) >= NR_syscalls)

int main(void)
{
	struct { int nr; int reject; const char *why; } t[] = {
