		{ 312,    1, "NR_syscalls (first out of range)" },
		{ 313,    1, "NR_syscalls+1" },
		{ 983045, 1, "ARM private syscall (CVE trigger)" },
	};
	int i, fail = 0;
	for (i = 0; i < (int)(sizeof(t)/sizeof(t[0])); i++) {
		int got = GUARD(t[i].nr);
		printf("nr=%-7d reject=%d expected=%d %s  # %s\n",
		       t[i].nr, got, t[i].reject,
		       got == t[i].reject ? "OK" : "FAIL", t[i].why);
		if (got != t[i].reject)
			fail = 1;
	}
	printf("%s\n", fail ? "BOUNDARY_FAIL" : "BOUNDARY_OK");
	return fail;
}

